using VMLAssembler;

namespace VMLTranslators
{
    /// <summary>
    /// PowerPC (PPC) 转译器
    /// 32位 PowerPC 架构（Book E / classic PPC32）
    /// 虚拟寄存器映射：
    ///   R0-R31 → PowerPC GPR r0-r31
    ///   F0-F31 → PowerPC FPR f0-f31 (浮点)
    /// </summary>
    public class TranslatorPowerPC : Translator32bit
    {
        public override string ARCH_NAME => "PowerPC";

        protected override string[] ContextRegNames() => new[] { "r0", "r3", "r4", "r5", "r6", "r7", "r8", "r9", "r10", "r11", "r12", "r14", "r15" };
        protected override string NativeInt(int vector) => "sc";
        protected override string NativeIret() => "rfi";
        protected override string NativeCli() => "";
        protected override string NativeSti() => "";
        protected override void EmitNativeCli()
        {
            Emit("        andi. r3, r3, 0x7FFF");
            Emit("        mtmsr r3");
        }
        protected override void EmitNativeSti()
        {
            Emit("        ori r3, r3, 0x8000");
            Emit("        mtmsr r3");
        }
        protected override void EmitSaveContext()
        {
            Emit("        stwu r1, -64(r1)");
            int off = 4;
            foreach (var r in ContextRegNames())
            {
                Emit($"        stw {r}, {off}(r1)");
                off += 4;
            }
        }
        protected override void EmitRestoreContext()
        {
            int off = 4;
            foreach (var r in ContextRegNames())
            {
                Emit($"        lwz {r}, {off}(r1)");
                off += 4;
            }
            Emit("        addi r1, r1, 64");
        }

        private readonly Dictionary<int, string> REGISTER_MAP = new Dictionary<int, string>
        {
            { 0, "r0" }, { 1, "r1" }, { 2, "r2" }, { 3, "r3" },
            { 4, "r4" }, { 5, "r5" }, { 6, "r6" }, { 7, "r7" },
            { 8, "r8" }, { 9, "r9" }, { 10, "r10" }, { 11, "r11" },
            { 12, "r12" }, { 13, "r13" }, { 14, "r14" }, { 15, "r15" },
            { 16, "r16" }, { 17, "r17" }, { 18, "r18" }, { 19, "r19" },
            { 20, "r20" }, { 21, "r21" }, { 22, "r22" }, { 23, "r23" },
            { 24, "r24" }, { 25, "r25" }, { 26, "r26" }, { 27, "r27" },
            { 28, "r28" }, { 29, "r29" }, { 30, "r30" }, { 31, "r31" }
        };

        // PowerPC ABI:
        // r1 = SP (栈指针), r2 = TOC指针, r3-r10 = 参数/返回值
        // r11 = 帧指针/局部, r12 = 跳转桩, r13 = 小数据区指针
        private readonly string[] FPR_MAP = {
            "f0","f1","f2","f3","f4","f5","f6","f7",
            "f8","f9","f10","f11","f12","f13","f14","f15",
            "f16","f17","f18","f19","f20","f21","f22","f23",
            "f24","f25","f26","f27","f28","f29","f30","f31"
        };

        public TranslatorPowerPC(VmlProgram vmlProgram) : base(vmlProgram) { }

        protected override void EmitHeader()
        {
            Emit("# PowerPC 32-bit Assembly - Translated from VML");
            Emit("# Generated by VML Translator");
            Emit("# Assembler: powerpc-as / gas (binutils)");
            Emit("");
            Emit("        .abicalls");
            Emit("        .text");
            Emit("        .globl main");
            Emit("        .align 2");
            Emit("");
        }

        protected override void EmitDataSection()
        {
            if (VmlProgram.DataSection.Count > 0)
            {
                Emit("");
                Emit("        .data");
                Emit("        .align 2");
                foreach (var kvp in VmlProgram.DataSection)
                {
                    string name = kvp.Key;
                    object value = kvp.Value;

                    if (value is string strValue)
                    {
                        Emit($"        .globl  {name}");
                        Emit($"{name}:");
                        Emit($"        .string \"{strValue}\"");
                        Emit($"        .align 2");
                    }
                    else if (value is System.Collections.IList listValue)
                    {
                        Emit($"        .globl  {name}");
                        Emit($"{name}:");
                        foreach (var item in listValue)
                        {
                            if (int.TryParse(item.ToString(), out int intValue))
                                Emit($"        .word   {intValue}");
                        }
                    }
                    else if (int.TryParse(value.ToString(), out int intValue))
                    {
                        Emit($"        .globl  {name}");
                        Emit($"{name}:");
                        Emit($"        .word   {intValue}");
                    }
                }
                Emit("");
            }
        }

        protected override void EmitCode()
        {
            Emit("        .text");
            Emit("        .align 2");
            Emit("");

            foreach (var instr in VmlProgram.Instructions)
            {
                if (!string.IsNullOrEmpty(instr.Label))
                {
                    Emit($"{instr.Label}:");
                }
                NormalizeAndTranslate(instr);
            }
        }

        protected override void TranslateInstruction(Instruction instr)
        {
            // NormalizeBinaryOp handled by BaseTranslator.NormalizeAndTranslate
            switch (instr.Opcode)
            {
                                                case OpCode.ADD:
                    TranslateAdd(instr);
                    break;
                case OpCode.SUB:
                    TranslateSub(instr);
                    break;
                case OpCode.MUL:
                    TranslateMul(instr);
                    break;
                case OpCode.DIV:
                    TranslateDiv(instr);
                    break;
                case OpCode.MOVE:
                    TranslateMove(instr);
                    break;
                case OpCode.CMP:
                    TranslateCmp(instr);
                    break;
                case OpCode.AND:
                    Emit($"        and {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.OR:
                    Emit($"        or {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.XOR:
                    Emit($"        xor {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.NOT:
                    Emit($"        not {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.SHL:
                    Emit($"        slw {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.SHR:
                    Emit($"        srw {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.INC:
                    Emit($"        addi {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, 1");
                    break;
                case OpCode.DEC:
                    Emit($"        addi {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, -1");
                    break;
                case OpCode.NEG:
                    Emit($"        neg {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.JMP:
                    Emit($"        b {instr.Operands[0].Value}");
                    break;
                case OpCode.JZ:
                case OpCode.JE:
                    Emit($"        beq {instr.Operands[0].Value}");
                    break;
                case OpCode.JNZ:
                case OpCode.JNE:
                    Emit($"        bne {instr.Operands[0].Value}");
                    break;
                case OpCode.JL:
                    Emit($"        blt {instr.Operands[0].Value}");
                    break;
                case OpCode.JLE:
                    Emit($"        ble {instr.Operands[0].Value}");
                    break;
                case OpCode.JG:
                    Emit($"        bgt {instr.Operands[0].Value}");
                    break;
                case OpCode.JGE:
                    Emit($"        bge {instr.Operands[0].Value}");
                    break;
                case OpCode.HALT:
                    Emit("        trap");
                    break;
                case OpCode.NOP:
                    Emit("        nop");
                    break;
                case OpCode.STI:
                // CLI/STI/INT/IRET handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.THROW:
                    Emit("        trap");
                    break;
                case OpCode.CATCH:
                    break;
                case OpCode.ENDCATCH:
                    break;
                case OpCode.PUSH:
                    Emit($"        stwu r1, -4(r1)");
                    Emit($"        stw {GetOperandValue(instr.Operands[0])}, 0(r1)");
                    break;
                case OpCode.POP:
                    Emit($"        lwz {GetOperandValue(instr.Operands[0])}, 0(r1)");
                    Emit($"        addi r1, r1, 4");
                    break;
                case OpCode.CALL:
                    Emit($"        bl {instr.Operands[0].Value}");
                    break;
                case OpCode.RET:
                    Emit("        blr");
                    break;
                // case OpCode.RET_VAL:
                //     Emit($"        mr r3, {GetOperandValue(instr.Operands[0])}");
                //     Emit("        blr");
                //     break;
                case OpCode.LABEL:
                    Emit($"{instr.Operands[0].Value}:");
                    break;
                case OpCode.SYSCALL:
                    Emit("        li r0, " + instr.Operands[0].Value);
                    Emit("        sc");
                    break;
                case OpCode.FADD:
                    Emit($"        fadd {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.FSUB:
                    Emit($"        fsub {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.FMUL:
                    Emit($"        fmul {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.FDIV:
                    Emit($"        fdiv {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.FNEG:
                    Emit($"        fneg {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.FCMP:
                    Emit($"        fcmpu cr1, {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}");
                    break;
                case OpCode.I2F:
                    Emit($"        fcfid {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}");
                    break;
                case OpCode.F2I:
                    Emit($"        fctidz {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}");
                    break;
                case OpCode.MOVEF:
                                // MOVEF store path: dest != REGISTER → FSTORE (handled via goto from MOVEF above)
                                case OpCode.TEST:
                    Emit($"        cmpwi {GetOperandValue(instr.Operands[0])}, 0");
                    break;
                case OpCode.MOD:
                    Emit($"        # MOD: div + multiply + subtract");
                    Emit($"        divw r0, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    Emit($"        mulhw r0, r0, {GetOperandValue(instr.Operands[2])}");
                    Emit($"        sub {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, r0");
                    break;
                case OpCode.FPUSH:
                case OpCode.FPOP:
                case OpCode.F2D:
                case OpCode.D2F:
                    Emit($"        # {instr.Opcode.ToString()} - 浮点栈操作/转换");
                    Emit($"        b __unimpl_{instr.Opcode.ToString().ToLower()}");
                    break;
                                                                                case OpCode.MOVEB:
                    Emit($"        rlwinm {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, 0, 24, 31");
                    break;
                case OpCode.MOVEH:
                    Emit($"        rlwinm {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, 0, 16, 31");
                    break;
                case OpCode.PUSHB:
                case OpCode.PUSHH:
                    Emit("        stwu r1, -4(r1)");
                    Emit($"        stw {GetOperandValue(instr.Operands[0])}, 0(r1)");
                    break;
                case OpCode.POPB:
                    Emit($"        lwz {GetOperandValue(instr.Operands[0])}, 0(r1)");
                    Emit("        addi r1, r1, 4");
                    Emit($"        rlwinm {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, 0, 24, 31");
                    break;
                case OpCode.POPH:
                    Emit($"        lwz {GetOperandValue(instr.Operands[0])}, 0(r1)");
                    Emit("        addi r1, r1, 4");
                    Emit($"        rlwinm {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, 0, 16, 31");
                    break;
                case OpCode.ENTER:
                    Emit($"        stwu r1, -{(instr.Operands.Count > 0 ? instr.Operands[0].Value : 0)}(r1)");
                    Emit("        mflr r0");
                    Emit("        stw r0, 4(r1)");
                    break;
                case OpCode.LEAVE:
                    Emit("        lwz r0, 4(r1)");
                    Emit("        mtlr r0");
                    if (instr.Operands.Count > 0)
                        Emit($"        addi r1, r1, {instr.Operands[0].Value}");
                    else
                        Emit("        addi r1, r1, 0");
                    Emit("        blr");
                    break;                                case OpCode.SHLV:
                    Emit($"        slw {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.SHRV:
                    Emit($"        srw {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.ZERO:
                    Emit($"        li {GetOperandValue(instr.Operands[0])}, 0");
                    break;
                case OpCode.BREAK:
                    Emit("        tw 31, r0, r0");
                    break;
                // OpCode.ASM handled by BaseTranslator.TryTranslateCommonOpcode
                // OpCode.CHIPASM handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.I2D:
                case OpCode.D2I:
                // 符号扩展/条件移动/循环移位 (v1.66.28+)
                case OpCode.SEXTB: case OpCode.SEXTH:
                case OpCode.CMOVZ: case OpCode.CMOVNZ:
                case OpCode.ROL: case OpCode.ROR:
                    Emit($"        bl __{instr.Opcode.ToString().ToLower()}");
                    break;
                default:
                    Emit($"        # UNIMPLEMENTED: {instr.Opcode.ToString()} {string.Join(", ", instr.Operands)}");
                    break;
            }
        }

        private void TranslateLoad(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            if (src.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src);
                Emit($"        li {GetOperandValue(dst)}, {value}");
            }
            else if (src.Type == OperandType.MEMORY)
            {
                Emit($"        lwz {GetOperandValue(dst)}, {src.Value}(0)");
            }
            else if (src.Type == OperandType.REGISTER)
            {
                Emit($"        mr {GetOperandValue(dst)}, {GetOperandValue(src)}");
            }
        }

        private void TranslateStore(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            if (src.Type == OperandType.REGISTER)
            {
                if (dst.Type == OperandType.MEMORY)
                {
                    Emit($"        stw {GetOperandValue(src)}, {dst.Value}(0)");
                }
                else if (dst.Type == OperandType.REGISTER)
                {
                    Emit($"        mr {GetOperandValue(dst)}, {GetOperandValue(src)}");
                }
            }
        }

        private void TranslateAdd(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                if (value >= -32768 && value <= 32767)
                    Emit($"        addi {GetOperandValue(dst)}, {GetOperandValue(src1)}, {value}");
                else
                    Emit($"        lis r0, {value >> 16}");
                    Emit($"        ori r0, r0, {value & 0xFFFF}");
                    Emit($"        add {GetOperandValue(dst)}, {GetOperandValue(src1)}, r0");
            }
            else
            {
                Emit($"        add {GetOperandValue(dst)}, {GetOperandValue(src1)}, {GetOperandValue(src2)}");
            }
        }

        private void TranslateSub(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                Emit($"        subfic {GetOperandValue(dst)}, {GetOperandValue(src1)}, {value}");
            }
            else
            {
                Emit($"        subf {GetOperandValue(dst)}, {GetOperandValue(src2)}, {GetOperandValue(src1)}");
            }
        }

        private void TranslateMul(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];
            Emit($"        mullw {GetOperandValue(dst)}, {GetOperandValue(src1)}, {GetOperandValue(src2)}");
        }

        private void TranslateDiv(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];
            Emit($"        divw {GetOperandValue(dst)}, {GetOperandValue(src1)}, {GetOperandValue(src2)}");
        }

        private void TranslateMove(Instruction instr)
        {
            // v1.65.167+: 统一 MOVE — MEM/LABEL dest → Store, 其他 → Load
            if (instr.Operands[0].Type == OperandType.MEMORY ||
                instr.Operands[0].Type == OperandType.INDIRECT ||
                instr.Operands[0].Type == OperandType.LABEL)
            {
                TranslateStore(instr);
                return;
            }
            TranslateLoad(instr);
        }

        private void TranslateCmp(Instruction instr)
        {
            var src1 = instr.Operands[0];
            var src2 = instr.Operands[1];
            if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                Emit($"        cmpwi cr0, {GetOperandValue(src1)}, {value}");
            }
            else
            {
                Emit($"        cmpw cr0, {GetOperandValue(src1)}, {GetOperandValue(src2)}");
            }
        }

        protected override string MapRegister(int regNum)
        {
            if (regNum < 0) return "r0";
            if (regNum > 31) return "r31";
            return REGISTER_MAP.TryGetValue(regNum, out string reg) ? reg : $"r{regNum}";
        }
    }
}
